  async function open(options){const opts=options||{};moveContext=null;edgeEditId='';saveInFlight=false;activeCharacter=opts.character||null;notify=typeof opts.notify==='function'?opts.notify:()=>{};saveHandler=typeof opts.onSave==='function'?opts.onSave:null;presetHandler=typeof opts.onPresetAction==='function'?opts.onPresetAction:null;userPresets=clone(opts.userPresets||[]);if(!activeCharacter)return;if(!ui)bindDom();ui.title.textContent=`${activeCharacter.name||'冒険者'} — AIチップ編集`;ui.overlay.classList.add('open');ui.overlay.setAttribute('aria-hidden','false');document.body.style.overflow='hidden';ui.state.textContent='正式AI Masterを読込中…';try{const loadedCatalog=await Catalog.load({aiUrl:opts.aiUrl,skillUrl:opts.skillUrl,templateUrl:opts.templateUrl,tags:opts.tags,tag_categories:opts.tag_categories});catalog=Catalog.filterSkills(loadedCatalog,activeCharacter.skills||[]);}catch(error){catalog=Catalog.filterSkills(Catalog.normalize([],[],[],[]),activeCharacter.skills||[]);notify(String(error?.message||error),'bad');}const key=String(activeCharacter.id||'default');if(!sessions.has(key))sessions.set(key,createSession(catalog,{program:opts.program,layout:opts.layout,program_id:`AIP-DRAFT-${key.replace(/[^A-Za-z0-9_.-]/g,'_')}`,layout_id:'AIL-0001',name:`${activeCharacter.name||''} AI`}));activeSession=sessions.get(key);activeSession.setCatalog?.(catalog);savedDocumentSignature=opts.program&&opts.layout?documentsSignature(opts.program,opts.layout):'';issueCursor=0;renderBoard();}
