      graphTools:$('aiGraphTools'),edgeFrom:$('aiEdgeFrom'),edgeKind:$('aiEdgeKind'),edgeTo:$('aiEdgeTo'),edgeSubroutine:$('aiEdgeSubroutine'),edgeReturnTo:$('aiEdgeReturnTo'),edgeApply:$('aiEdgeApply'),edgeCancelEdit:$('aiEdgeCancelEdit'),edgeList:$('aiEdgeList'),subroutineEntry:$('aiSubroutineEntry'),subroutineAdd:$('aiSubroutineAdd'),subroutineList:$('aiSubroutineList')
